head.script:
scwin.trigger1_onclick = function(e) {
    //alert(JSON.stringify(gridView1.getDataListInfo()));
    console.log(JSON.stringify(gridView1.getDataListInfo()));
    window.log = gridView1.getDataListInfo();
};
scwin.trigger2_onclick = function(e) {
    var column1 = gridView1.cellInfoHash[gridView1.getColumnID(0)];
    //alert(JSON.stringify(column1.getColumnDataListInfo()));
    window.log1 = column1.getColumnDataListInfo();
};
scwin.trigger3_onclick = function(e) {
    //alert(JSON.stringify(input1.getDataListInfo()));
    window.log2 = input1.getDataListInfo();
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 trigger1 부분을 확인한다.
    //1. In the Script tab, check the trigger1 section.
    //Verify step 1. alert (JSON.stringify (gridView1.getDataListInfo ()));
    //Test step 2. trigger2 부분을 확인한다.
    //2. Check the trigger2 section.
    //Verify step 2. alert (JSON.stringify (column1.getColumnDataListInfo ()));
    //Test step 3. trigger3 부분을 확인한다.
    //3. Check the trigger3 section.
    //Verify step 3. alert (JSON.stringify (input1.getDataListInfo ()));
    //Test step 4. 브라우저에서 getDataListInfo(GridView) 버튼을 클릭한다.
    //4. In your browser, click the getDataListInfo (GridView) button.
    //Verify step 4. The "id": "dataList1" popup is created.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("assert", "window.log.id == 'dataList1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. getColumnDataListInfo(col1) 버튼을 클릭한다. 
    //5. Click the getColumnDataListInfo (col1) button.
    //Verify step 5. 'nodest': 'data: dataList2', 'id': 'dataList2', 'value': 'value', 'label'
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    //WebSquare.wUnit.addCommand("assert", "window.log1.nodeset == 'data:dataList2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1.id == 'dataList2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1.value == 'value'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1.label == 'email'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. getDataListInfo버튼을 클릭한다.
    //6. Click the getDataListInfo button.
    //Verify step 6. 'id': 'dataList1', 'ref': 'data: dataList1'
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("assert", "window.log2.id == $p.id+'dataList1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log2.ref == 'data:dataList1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined; 
	window.log1 = undefined; 
	window.log2 = undefined;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018		
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
